{
  "missing_information": [
    {
      "category": "Tool Selection Logic",
      "gap": "No criteria are given for how or why a particular measurement tool is chosen for a given wafer",
      "why_it_matters": "Without knowing the selection logic (e.g., wafer type, lot priority, tool availability), it is impossible to model the branching point in the workflow or assess whether tool assignment can be automated"
    },
    {
      "category": "Tool-Specific Steps",
      "gap": "The preparation and measurement steps for each individual tool are not described",
      "why_it_matters": "Each tool variant represents a distinct process path; without step-level detail, the workflow cannot be reconstructed or compared for automation potential"
    },
    {
      "category": "Result Recording Method",
      "gap": "It is unclear how the engineer records the measurement result (e.g., manual entry into a system, paper log, automated data capture) and what data fields are captured",
      "why_it_matters": "The recording method directly determines whether this step is a candidate for automation and affects data quality and traceability"
    },
    {
      "category": "Decision After Measurement",
      "gap": "No information is provided about what happens after the result is recorded, such as pass/fail checks, routing decisions, or rework triggers",
      "why_it_matters": "Post-measurement decisions are critical workflow steps; omitting them makes it impossible to assess end-to-end automation opportunities or exception handling"
    },
    {
      "category": "Tool Availability and Scheduling",
      "gap": "There is no information about how tool availability or queuing is managed when multiple wafers compete for the same tool",
      "why_it_matters": "Queuing and scheduling logic affects cycle time and is often a key automation target in semiconductor workflows"
    },
    {
      "category": "Roles and Responsibilities",
      "gap": "It is unclear which actions are performed by the engineer versus automated systems or technicians, and whether a review or approval step exists",
      "why_it_matters": "Role boundaries determine which steps require human intervention and which are candidates for full or partial automation"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What criteria determine which measurement tool is selected for a given wafer, and who or what makes that selection decision?",
      "targets": ["Tool Selection Logic"]
    },
    {
      "id": "Q2",
      "question": "Can you walk through the preparation and measurement steps for each tool variant, noting where the steps differ from one another?",
      "targets": ["Tool-Specific Steps"]
    },
    {
      "id": "Q3",
      "question": "How does the engineer record the measurement result—what system or medium is used, and which specific data fields are entered or captured?",
      "targets": ["Result Recording Method"]
    },
    {
      "id": "Q4",
      "question": "After the measurement result is recorded, what happens next—is there a pass/fail evaluation, a routing decision, or any other downstream action triggered by the result?",
      "targets": ["Decision After Measurement"]
    },
    {
      "id": "Q5",
      "question": "How is tool availability managed when multiple wafers need to be measured—is there a queue, a scheduling system, or a manual coordination process?",
      "targets": ["Tool Availability and Scheduling"]
    },
    {
      "id": "Q6",
      "question": "Which steps in the workflow are performed solely by the engineer, and are any steps currently executed or assisted by automated systems or other roles?",
      "targets": ["Roles and Responsibilities"]
    }
  ]
}
